-- Batch update templates 20-24 with full user-provided content.
UPDATE public.prd_templates
SET description = $desc$A comprehensive guide for planning and executing a product release, covering all critical aspects from product overview to measurement and success criteria.$desc$,
    structure = $json${"instructions": "Write with enough specificity that any team member could execute the plan independently. Include concrete dates, owners, and dependencies. Be brutally clear about what is included vs. excluded from scope. Success criteria should be measurable from day one. The RACI matrix should cover every major workstream with no ambiguity.", "sections": [{"name": "Product Overview", "guidelines": "What is being released, who it is for, and why it matters.\n\n### Summary\n- Product/Feature: [Name and brief description]\n- Target audience: [Who benefits from this release]\n- Value proposition: [Key benefit in one sentence]\n- Strategic alignment: How this release supports broader product/business goals\n\n### Release Type\n- Major release / Feature launch / Improvement / Hotfix\n- New product vs. update to existing"}, {"name": "Release Objectives", "guidelines": "What this release aims to achieve — using SMART goals.\n\n### Primary Objectives\nFor each objective:\n- Goal: [Specific, measurable outcome]\n- Metric: [How it will be measured]\n- Target: [Concrete number or threshold]\n- Timeline: [When we expect to see results]\n\n### Relevance\nHow each objective ties to team KPIs and company strategy.\n\n### Achievability\nAssessment of feasibility given time and resources. Flag any objectives that are stretch goals."}, {"name": "Release Scope", "guidelines": "What is and is not included in this release.\n\n### Included Features\nFor each feature:\n- Feature: [Name] — [Brief description and purpose]\n- Priority: P0 / P1 / P2\n\n### Bug Fixes\n- [Bug description] — [Impact and urgency]\n\n### Excluded / Deferred\n- [Feature/fix] — Deferred because [reason]. Planned for [timeframe].\n\n### Non-Functional Requirements\n- Performance: [Targets — load time, throughput, etc.]\n- Security: [Requirements — auth, encryption, audit logging]\n- Accessibility: [WCAG level and specific requirements]\n\n### Dependencies & Limitations\n- External dependencies that could affect the release\n- Known limitations of the current release"}, {"name": "Stakeholders & RACI", "guidelines": "Who is involved and what they are responsible for.\n\n### RACI Matrix\n| Activity | Responsible | Accountable | Consulted | Informed |\n|----------|-------------|-------------|-----------|----------|\n| Feature development | [Name/Team] | [Name] | [Names] | [Names] |\n| QA & testing | [Name/Team] | [Name] | [Names] | [Names] |\n| Go/no-go decision | [Name] | [Name] | [Names] | [Names] |\n| Marketing & comms | [Name/Team] | [Name] | [Names] | [Names] |\n| Customer support | [Name/Team] | [Name] | [Names] | [Names] |\n\n### External Stakeholders\n- Partners, vendors, or customers involved in the release\n- Their roles and communication plan"}, {"name": "Release Timeline & Milestones", "guidelines": "The schedule from now to release and beyond.\n\n### Key Milestones\n| Milestone | Date | Owner | Status |\n|-----------|------|-------|--------|\n| Feature freeze | [Date] | [Name] | |\n| QA complete | [Date] | [Name] | |\n| Staging deploy | [Date] | [Name] | |\n| Go/no-go decision | [Date] | [Name] | |\n| Production deploy | [Date] | [Name] | |\n| Post-release review | [Date] | [Name] | |\n\n### Deploy Plan\n- Strategy: Big bang / Rolling / Canary / Feature flag\n- Rollback trigger: [What metric or condition triggers rollback]\n- Rollback procedure: [Steps to revert]"}, {"name": "Risk Assessment", "guidelines": "What could go wrong and how to handle it.\n\n### Risk Matrix\n| Risk | Likelihood | Impact | Mitigation | Owner |\n|------|------------|--------|------------|-------|\n| [Risk 1] | Low/Med/High | Low/Med/High | [Plan] | [Name] |\n| [Risk 2] | Low/Med/High | Low/Med/High | [Plan] | [Name] |\n\n### Common Release Risks\n- Critical bug found in staging\n- External dependency not ready\n- Performance degradation under production load\n- Negative user feedback requiring rapid response\n\n### Go/No-Go Criteria\nSpecific conditions that must be met for the release to proceed. Who makes the final call?"}, {"name": "Measurement & Success Criteria", "guidelines": "How you will know the release was successful.\n\n### Day-1 Metrics\n- Error rate stays below [threshold]\n- Performance within [targets]\n- No P0 bugs reported\n\n### Week-1 Metrics\n- [Feature adoption metric]: [Target]\n- [User satisfaction metric]: [Target]\n- Support ticket volume: [Expected vs. threshold]\n\n### Month-1 Metrics\n- [Business outcome metric]: [Target]\n- [Retention/engagement metric]: [Target]\n\n### Review\n- When is the post-release review?\n- What format (metrics dashboard, team meeting, written report)?\n- How do learnings feed into the next release cycle?"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Release Plan$name$;

UPDATE public.prd_templates
SET description = $desc$A self-contained product spec designed to be pasted directly into AI prototyping tools like v0, Bolt, Lovable, or Replit. Covers what to build, how it should look, the tech stack, and key user flows — everything these tools need to generate a working prototype.$desc$,
    structure = $json${"instructions": "Write this as a clear, complete spec that someone could paste directly into v0, Bolt, Lovable, or Replit and get a working prototype on the first try. Be extremely specific about visual design (name exact component libraries, colors, layouts) and user interactions (what happens on every click, submit, and navigation). Tech stack choices should be explicit — these tools need exact framework and library names, not categories. Keep the language direct and imperative. The spec should be self-contained: an AI code generator reading only this document should produce something that looks and works right without follow-up questions.", "sections": [{"name": "Product Overview", "guidelines": "What you are building in 2-3 sentences: the core concept, who it is for, and the primary action users take. Be specific about what makes this product useful — not just what it is, but why someone would use it. Include the scope for this prototype: what is included and what will be built later."}, {"name": "Design & Visual Style", "guidelines": "Specific design direction for the AI tool to follow:\n- Component library: shadcn/ui, Material UI, Chakra UI, DaisyUI, or custom\n- Styling framework: Tailwind CSS, CSS Modules, vanilla CSS\n- Color scheme: Primary, secondary, and accent colors (hex codes or descriptive palette like \"neutral with blue accents\")\n- Theme: Light mode, dark mode, or both with toggle\n- Layout style: Sidebar nav, top nav, dashboard grid, single-page scroll, etc.\n- Typography & spacing: Dense/compact vs. spacious, font preferences\n- Reference sites: 1-2 existing products whose visual style to emulate"}, {"name": "Tech Stack", "guidelines": "The exact technologies the prototype should use. Be specific — AI tools generate better code with explicit choices:\n- Framework: Next.js (App Router), Vite + React, Astro, SvelteKit, Nuxt, etc.\n- Language: TypeScript or JavaScript\n- Database: Supabase, Neon, PlanetScale, Firebase, or local SQLite\n- ORM: Prisma, Drizzle, or direct SQL\n- Auth: Clerk, NextAuth, Supabase Auth, or none for prototype\n- Hosting target: Vercel, Netlify, Railway, or local only\n- Key libraries: Any specific packages to use (date handling, charts, rich text, etc.)"}, {"name": "Pages & Navigation", "guidelines": "Every page or screen in the prototype with its URL path and purpose:\n- Page name (/path): What the user sees and does on this page\n\nSpecify the navigation structure: sidebar links, top nav items, tab bars, or breadcrumbs. Note which pages require authentication and which are public. Describe the landing/home page experience for both logged-in and logged-out users."}, {"name": "Core User Flows", "guidelines": "The 2-4 most important user interactions, described step by step:\n\nFlow 1: [Name]\n1. User lands on [page] and sees [what]\n2. User clicks/types [action]\n3. System responds with [result]\n4. User sees [confirmation/next state]\n\nInclude the first win moment — the first time the user gets value from the product. Cover the happy path in detail. Note key transitions, loading states, and success/error feedback."}, {"name": "Data Model & Backend", "guidelines": "The core data entities the prototype needs, with key fields:\n- Entity (field: type, field: type, ...)\n- Relationships between entities\nSpecify any API endpoints or server actions needed. Note if the prototype should use real data persistence or mock/seed data. Include any background jobs, webhooks, or scheduled tasks if relevant."}, {"name": "Key Components", "guidelines": "Specific UI components that need special attention beyond standard page layouts. Examples: a drag-and-drop kanban board, a real-time chat widget, a rich text editor, a data table with sorting/filtering, a multi-step form wizard, a file upload area. For each, describe the expected behavior and any library preferences."}, {"name": "AI Generation Notes", "guidelines": "Additional instructions specifically for the AI code generation tool:\n- Features to skip or stub out for now (e.g., skip email notifications, just log to console)\n- Performance considerations (use server components where possible)\n- Specific patterns to follow or avoid\n- Seed data or placeholder content to include\n- Any known limitations of the target platform to work around\n- Mobile responsiveness requirements"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Spec for AI Prototyping$name$;

UPDATE public.prd_templates
SET description = $desc$This template provides a comprehensive structure for documenting the technical design of a product or feature, ensuring all critical aspects are covered.$desc$,
    structure = $json${"instructions": "Write for the engineers who will implement this. Include specific technology choices with clear rationale. Data structures should specify types, relationships, and constraints. API sections should include request/response examples. Address scalability for realistic growth scenarios. Deployment steps should be concrete and reproducible.", "sections": [{"name": "Product Overview", "guidelines": "Context for the technical design.\n\n### Purpose\n- What problem this solves and the opportunity it captures\n- Specific user scenarios that illustrate the need\n\n### Target Audience\n- Key user personas and their needs\n- How the product addresses their pain points\n\n### Expected Outcomes\n- Tangible and intangible benefits\n- Key metrics / KPIs that will measure success\n- Short-term vs. long-term impact"}, {"name": "Architecture", "guidelines": "The structural design of the system.\n\n### High-Level Architecture\nDescribe how the major components connect. Include:\n- Frontend, backend, database, message queue, external services\n- Communication protocols (REST, GraphQL, WebSocket, gRPC)\n- Design patterns used (MVC, event-driven, CQRS, etc.)\n\n### Data Structures & Algorithms\n- Core data structures with justification for selection\n- Key algorithms and their complexity characteristics\n- Scalability and performance considerations\n\n### System Interfaces\n- API endpoints: Key routes with methods and purpose\n- Third-party integrations: External services and protocols\n- Internal modules: How components communicate internally\n\n### User Interface\n- Main UI components and interaction patterns\n- Wireframes or mockups (reference or describe)\n- Accessibility and responsive design approach"}, {"name": "Data Model", "guidelines": "How data is structured, stored, and accessed.\n\n### Entities\nFor each core entity:\n\nEntityName\n- field: type (constraints)\n- field: type (constraints)\n\n\n### Relationships\n- Entity A -> Entity B: relationship type and FK behavior\n- Join tables for many-to-many relationships\n\n### Storage\n- Database technology and hosting\n- Caching strategy (Redis, in-memory, CDN)\n- File/blob storage approach\n\n### Data Flow\nHow data moves through the system from user input to persistence and back."}, {"name": "Testing Plan", "guidelines": "How the product will be validated at every level.\n\n### Testing Strategy\n- Unit tests: What is tested, framework, coverage targets\n- Integration tests: API and service interaction testing\n- E2E tests: Critical user flow testing, framework (Playwright, Cypress)\n- Performance tests: Load testing approach and targets\n\n### Testing Tools\n- Frameworks: [e.g., Vitest, Jest, Playwright]\n- CI integration: How tests run automatically\n- Code coverage: Targets and enforcement\n\n### Key Test Cases\nCritical scenarios to validate:\n- Happy path for core user flows\n- Edge cases and error handling\n- Security-sensitive operations\n- Performance under expected load\n\n### Reporting\n- How test results are tracked and communicated\n- Dashboard or tool for ongoing visibility"}, {"name": "Deployment Plan", "guidelines": "How the product moves from code to production.\n\n### Environment Setup\n- Development: Local setup, seed data, hot reload\n- Staging: Configuration, data sources, access control\n- Production: Infrastructure, scaling, monitoring\n\n### CI/CD Pipeline\n- Build steps: lint, type check, test, build\n- Deployment trigger: merge to main, manual, scheduled\n- Preview deployments for PRs\n\n### Deploy Process\n1. [Step with verification checkpoint]\n2. [Step with verification checkpoint]\n3. [Step with verification checkpoint]\n\n### Rollback Strategy\n- How to revert a bad deploy\n- Database migration rollback approach\n- Feature flags for gradual rollout\n\n### Post-Deploy Verification\n- Smoke tests to run after deploy\n- Monitoring dashboards to watch\n- Alert thresholds for automatic rollback"}, {"name": "Security & Performance", "guidelines": "Non-functional requirements and how they are addressed.\n\n### Security\n- Authentication and authorization approach\n- Input validation and sanitization\n- Secrets management (env vars, vault)\n- Dependency vulnerability scanning\n- OWASP Top 10 considerations relevant to this product\n\n### Performance\n- Targets: Page load < [X]s, API response < [X]ms, throughput > [X] req/s\n- Optimization: Caching, lazy loading, code splitting, CDN\n- Monitoring: APM tools, error tracking, custom metrics\n- Scaling: Horizontal vs. vertical, auto-scaling configuration\n\n### Observability\n- Logging strategy: What is logged, structured format, retention\n- Metrics: Key dashboards and what they track\n- Alerting: What triggers alerts and who responds"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Technical Design Document$name$;

UPDATE public.prd_templates
SET description = $desc$This template outlines the necessary components for planning and executing a usability test. It helps in defining objectives, methodology, environment, measures, and reporting for effective usability testing.$desc$,
    structure = $json${"instructions": "Design tests that will change product decisions — avoid testing just to check a box. Participant criteria should reflect real user segments, not convenience samples. Tasks should be realistic end-to-end scenarios. Define specific pass/fail thresholds. Include a decision framework: what concrete changes will be made based on which outcomes.", "sections": [{"name": "Test Overview", "guidelines": "Why you are running this test and what you hope to learn.\n\n### Purpose\n- What usability questions this test will answer\n- What product decisions depend on the results\n\n### Scope\n- Which product area, feature, or flow is being tested\n- What is NOT being tested (out of scope)\n\n### Stakeholders\n| Role | Person | Responsibility |\n|------|--------|----------------|\n| Test facilitator | [Name] | Runs sessions, asks questions |\n| Note-taker | [Name] | Captures observations in real time |\n| Observer(s) | [Names] | Watches sessions, adds notes |\n| Decision maker | [Name] | Acts on findings |"}, {"name": "Test Design", "guidelines": "How the test will be structured and conducted.\n\n### Methodology\n- Type: Moderated / Unmoderated / Remote / In-person\n- Format: Think-aloud, task-based, comparative (A vs. B), exploratory\n- Duration: [X] minutes per session\n- Number of sessions: [X] participants\n\n### Participant Criteria\n- Include: [Demographics, experience level, user segment]\n- Exclude: [Who should NOT participate and why]\n- Recruitment source: Customer list, panel service, social media\n- Incentive: [What participants receive]\n\n### Test Environment\n- Device/browser: Specific requirements\n- Prototype or live product: Which version is being tested\n- Tools: UserTesting, Maze, Lookback, Zoom, etc."}, {"name": "Tasks & Scenarios", "guidelines": "What participants will be asked to do.\n\n### Scenarios\nRealistic contexts that set up the tasks (do not hint at the UI):\n\nScenario 1: [Name]\n\"Imagine you are [context]. You need to [goal].\"\n\n### Tasks\nFor each task:\n- Task: [What the participant should accomplish]\n- Scenario: [Which scenario it belongs to]\n- Starting point: [Where they begin]\n- Success criteria: [How you know they completed it]\n- Time limit: [Max time before moving on]\n\n### Post-Task Questions\n- On a scale of 1-7, how easy was that task?\n- What was confusing or unclear?\n- What would you expect to happen next?"}, {"name": "Metrics & Success Criteria", "guidelines": "How results will be measured.\n\n### Quantitative Metrics\n| Metric | Target | How Measured |\n|--------|--------|-------------|\n| Task completion rate | > [X]% | [Method] |\n| Time on task | < [X] min | [Method] |\n| Error rate | < [X]% | [Method] |\n| Satisfaction (post-task) | > [X]/7 | Rating scale |\n| SUS score | > [X] | Post-test survey |\n\n### Qualitative Metrics\n- Confusion points: Where users hesitate, backtrack, or express frustration\n- Mental model fit: Does the UI match what users expect?\n- Feature discovery: Do users notice key features without prompting?\n- Emotional response: Confidence, frustration, delight at key moments\n\n### Pass/Fail Thresholds\n- Pass: [Criteria] -> Proceed to launch\n- Conditional pass: [Criteria] -> Fix issues, retest specific areas\n- Fail: [Criteria] -> Redesign required before launch"}, {"name": "Session Guide", "guidelines": "Script and structure for running each test session.\n\n### Intro (5 min)\n- Welcome and set expectations\n- Explain think-aloud protocol\n- Confirm recording consent\n- Remind them: We are testing the product, not you\n\n### Warm-Up (5 min)\n- Background questions about their role and experience\n- Current workflow related to the product area\n\n### Tasks (30-40 min)\n- Walk through each task/scenario in order\n- Ask post-task rating after each task\n- Note where they struggle without intervening\n\n### Debrief (10 min)\n- Overall impressions\n- What was easiest? Most frustrating?\n- Would they use this? Why/why not?\n- Any features they expected but did not find?"}, {"name": "Analysis & Recommendations", "guidelines": "How findings become product decisions.\n\n### Analysis Framework\nFor each finding:\n- Finding: [What was observed]\n- Severity: Critical / Major / Minor / Cosmetic\n- Frequency: [X] of [Y] participants encountered this\n- Impact: Effect on task completion and satisfaction\n- Recommendation: Specific change to make\n\n### Deliverables\n- Findings summary: All issues ranked by severity and frequency\n- Highlight reel: 3-5 min video of key moments for stakeholders\n- Recommendation deck: Prioritized changes with effort estimates\n\n### Decision Framework\n- Critical: Must fix before launch — blocks core functionality\n- Major: Fix in next sprint — degrades experience significantly\n- Minor: Add to backlog — nice-to-have improvements\n- Cosmetic: Fix when convenient — polish items\n\n### Next Steps\n- Schedule follow-up test to validate fixes (if needed)\n- Timeline for implementing changes\n- When to test again"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Usability Test Plan$name$;

UPDATE public.prd_templates
SET description = $desc$Detailed profiles representing different user segments to create empathy and better design for user needs.$desc$,
    structure = $json${"instructions": "Create vivid, research-grounded personas that feel like real people — not marketing stereotypes. Include specific behavioral details that directly inform product decisions. Quotes should sound natural and reveal genuine frustrations or aspirations. Each persona should have distinct needs that lead to different product implications.", "sections": [{"name": "Persona Name", "guidelines": "A memorable, descriptive name that the team can reference in discussions.\n\n### Format\n- Name: A real-sounding first name + a descriptive qualifier\n- Example: Startup Sarah / Enterprise Eli / Freelancer Fran\n- Photo suggestion: Describe the type of stock photo that represents this persona\n\nThe name should instantly evoke who this person is — make it stick in the team's memory."}, {"name": "Demographics", "guidelines": "Factual information that sets the context for this persona's needs and behaviors.\n### Key Details\n- Age range: e.g., 28-35\n- Job title and seniority: e.g., Senior Product Manager\n- Company size: Startup (<50) / Mid-market (50-500) / Enterprise (500+)\n- Industry: e.g., SaaS, E-commerce, Healthcare\n- Location: Urban/suburban/remote, region\n- Technical skill: Non-technical / Technical-adjacent / Developer\n\nOnly include demographics that actually influence product decisions — skip what does not matter."}, {"name": "Goals", "guidelines": "What this persona is trying to achieve — both with your product and in their broader role.\n\n### Product Goals\nWhat they want to accomplish using your product:\n- Goal 1: [Specific outcome they want]\n- Goal 2: [Another specific outcome]\n\n### Career/Role Goals\nBroader objectives that your product helps with:\n- [Underlying motivation: look competent, save time, get promoted, reduce stress]\n\n### Jobs to Be Done\nThe job they are hiring your product to do:\n- When I [situation], I want to [motivation], so I can [expected outcome]"}, {"name": "Pain Points", "guidelines": "Specific frustrations this persona experiences — grounded in research, not assumptions.\n\n### Current Frustrations\nFor each pain point:\n- Pain: What specifically frustrates them\n- Frequency: How often they encounter this\n- Severity: Annoying / Painful / Blocking\n- Current workaround: What they do today to cope\n\n### Quotes from Research\nDirect quotes that capture the frustration in their own words:\n- \"I spend half my Monday just pulling together the weekly numbers from three different tools.\"\n- \"I know there is a better way but I do not have time to figure it out.\""}, {"name": "User Journey", "guidelines": "How this persona typically interacts with your product category.\n\n### Discovery\n- How they first learn about products like yours\n- Where they go for information (Google, communities, peers, Twitter)\n\n### Evaluation\n- What criteria matter most when comparing options\n- Who else is involved in the decision (manager, team, IT)\n\n### Adoption\n- First actions they take when trying a new tool\n- What determines whether they stick with it or churn\n\n### Ongoing Usage\n- Typical frequency and depth of use\n- What triggers them to engage (notification, workflow, habit)"}, {"name": "Behavioral Traits", "guidelines": "Key characteristics that influence how this persona uses products.\n\n### Technology Behavior\n- Tool adoption: Early adopter / Pragmatist / Late majority\n- Learning style: Explores independently / Reads docs / Needs hand-holding\n- Platform preference: Mobile-first / Desktop / Both equally\n\n### Work Style\n- Decision making: Data-driven / Intuition-based / Consensus-seeking\n- Communication: Slack/async / Meetings / Email\n- Pace: Moves fast and iterates / Plans carefully before acting\n\n### Personality\n2-3 key adjectives that define how they approach problems (e.g., detail-oriented, pragmatic, skeptical, collaborative)."}, {"name": "Quotes from User Research", "guidelines": "Direct quotes from interviews, surveys, or support conversations that bring this persona to life.\n\n### Format\n\"[Quote that reveals a key insight about their needs or frustrations]\"\n— Context: [Where/when this was said]\n\n### Guidelines\n- Include 3-5 quotes that each reveal something different\n- Mix positive quotes (what they love) with negative (what frustrates them)\n- Quotes should feel real — messy, specific, and human\n- If using hypothetical quotes, base them closely on actual research themes"}, {"name": "Product Implications", "guidelines": "What this persona means for product decisions — the actionable takeaway.\n\n### Design Implications\n- UI complexity level this persona can handle\n- Key workflows to optimize for this persona\n- Onboarding approach that matches their learning style\n\n### Feature Priority\n- Features this persona values most\n- Features this persona does not care about\n- Gaps in the current product for this persona\n\n### Messaging\n- Value proposition that resonates with this persona\n- Language and tone that works (technical, simple, aspirational)\n- What competitors this persona is comparing you to"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$User Personas$name$;

